export const SETTINGS_DEFAULTS = {
  // --- General / Branding ---
  //
  // Every default in this block is the string that was previously HARDCODED at the
  // render site it now feeds. That matters: `getSetting` falls back to these, so a
  // platform with an empty `Setting` table must render exactly what it rendered
  // before the wiring landed. A default of "" here would have blanked the footer
  // tagline and produced an empty `mailto:` on /contact the moment these keys were
  // read for the first time.
  brand_name: "Nxeon",
  // Verbatim the copy that used to be inline in components/marketing/MarketingFooter.tsx.
  // The footer is this key's only consumer, so the panel now previews what actually ships.
  brand_tagline:
    "Premium NVMe cloud VPS hosting, provisioned in seconds. Built for developers, teams, and everything you ship.",
  // Was "". The contact page advertises this address in three places and every one of
  // them hardcoded it, so the panel showed a blank support email while the marketing
  // site published a real one — and reading the blank key would have shipped
  // `mailto:` with no recipient.
  support_email: "support@nxeon.cloud",
  // DNS zone that managed-Nextcloud (NxCloud) instances live under:
  // <subdomain>.<nxcloud_zone>. A wildcard *.nxcloud_zone → the instance VMs (or a
  // per-instance A record) must resolve for auto-TLS to issue. See worker/nxcloud.ts.
  nxcloud_zone: "nxcloud.nxeon.cloud",
  // Blank is legitimate for these two: `renderInvoiceHTML` omits the seller block
  // entirely when they are unset rather than printing an empty "From" address.
  company_legal_name: "",
  company_address: "",
  social_twitter: "",
  social_github: "",
  social_discord: "",
  social_linkedin: "",
  social_facebook: "",
  social_instagram: "",
  social_youtube: "",
  footer_text: "",
  // Raw provider <script> body injected by components/marketing/LiveChat.tsx.
  livechat_snippet: "",
  // AI chat assistant: when on, the live-chat widget answers with Claude before a
  // human engages, grounded on the operator knowledge base (lib/kb-system.ts) plus
  // retrieved FAQ/blog chunks — see lib/kb.ts + lib/kb-llm.ts. Sales-oriented: it
  // pushes toward signup, mentions the free-month promo, and offers the coupon
  // below when set. Off by default; needs an API key to actually call Claude.
  kb_bot_enabled: "false",
  // Anthropic API key for the chat assistant (encrypted at rest). If blank, the
  // assistant falls back to the platform ANTHROPIC_API_KEY env var, and if neither
  // is present, to the token-free retrieval answers. Stored as a "secret".
  kb_bot_api_key: "",
  // Model the assistant calls. Haiku 4.5 is the cost pick for a support bot
  // (~pennies/conversation); switch to a Sonnet/Opus id for more polish.
  kb_bot_model: "claude-haiku-4-5",
  // Optional REAL coupon code (create it in the Coupons engine first). When set,
  // the assistant offers it by name to nudge a purchase. Blank = promo only.
  kb_bot_coupon: "",
  // Where the "a visitor wants a human" email goes. Blank falls back to support_email.
  kb_bot_agent_email: "",
  // Human-handoff window (seconds): after the bot escalates and emails an agent,
  // how long to wait for a live agent to join before posting the "no agents
  // available right now" fallback. Default 3 minutes.
  kb_bot_window_sec: "180",
  // Guardrail: max AI replies per conversation before it stops answering and
  // routes to a human (prevents runaway loops / token burn on one thread).
  kb_bot_max_replies: "16",
  // Guardrail: platform-wide daily cap on AI replies (a soft cost ceiling).
  // 0 = unlimited. When exceeded, the bot falls back to token-free answers.
  kb_bot_daily_cap: "1000",

export async function defaultTermMonths(): Promise<number> {
  const months = Number(await getSetting("default_term"));
  return VPS_TERMS.some((t) => t.months === months) ? months : VPS_TERMS[0].months;
}

/**
 * The public support address, guaranteed non-empty.
 *
 * Shared rather than inlined because it is rendered into `mailto:` hrefs on the public
 * contact page. `saveSettings` happily stores a blank string when an operator clears the
 * field, and `mailto:` with no recipient opens an empty compose window — a visitor who
 * clicks "Email our team" would be left with nowhere to send it and no error to explain
 * why. The hardcoded default is the address the marketing site has always published.
 */
export async function supportEmail(): Promise<string> {
  const v = (await getSetting("support_email")).trim();
  return v || SETTINGS_DEFAULTS.support_email;
}

